import 'package:flutter/material.dart';
import '../app.dart';
class StatementScreen extends StatelessWidget { const StatementScreen({super.key}); @override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Meu extrato')),body:FutureBuilder<Map<String,dynamic>>(future:context.read<AppState>().repository.statement(),builder:(context,s){if(s.hasError)return Center(child:Text('${s.error}'));if(!s.hasData)return const Center(child:CircularProgressIndicator());final d=s.data!;final t=d['totals'] as Map<String,dynamic>;final cs=d['contributions'] as List<dynamic>? ?? [];return ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Contribuições pagas: R$ ${t['contributions_paid']}'),Text('Pagamentos de empréstimos: R$ ${t['loan_payments']}'),Text('Empréstimos em aberto: R$ ${t['loan_outstanding']}')])),const SizedBox(height:12),const Text('Contribuições',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),...cs.map((x){final c=x as Map<String,dynamic>;return ListTile(title:Text(c['competence'].toString()),subtitle:Text('R$ ${c['amount']}'),trailing:Text('${c['status']}'));})]);}));}
}
